import {ROUTES,FRIEND_NAMES,canRoute,wakeFriend,completeRoute,jumpHit,flyStep,scanAt} from './companion-model.js';
import {drawCharacter} from './characters.js';

export function createCompanionUI(root,s,{onSave,onExit,onFinish,onSound}){
 let id='entry',mode='',marks=[],patches=new Set(),pos={x:.12,y:.85},aim={x:.3,y:.42},goal=null,busy=false,token=0,last=0;
 const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
 const actor=()=>`<canvas class="trail-actor" role="img" aria-label="${FRIEND_NAMES[ROUTES[id].who]} 토우"></canvas>`;
 function shell(title,body,instruction=''){
  root.classList.remove('hidden');root.dataset.route=id;root.dataset.mode=mode;
  root.innerHTML=`<header class="adv-top"><div><small>토우 친구 탐험 · ${s.friends.length}명과 함께</small><h2 tabindex="-1">${title}</h2></div><button type="button" data-trail="exit">탐험 지도</button></header>${instruction?`<p class="adv-instruction">${instruction}</p>`:''}${body}<p class="trail-fiction">토우의 능력으로 길을 여는 창작 놀이야. 유물은 손과 붓으로 조심조심!</p>`;
  root.scrollTop=0;paint(0);root.querySelector('h2')?.focus({preventScroll:true});
 }
 function wake(){mode='wake';shell('흙 속에서 누가 꼼지락?',`<div class="wake-stage">${actor()}${[0,1,2].map(n=>`<button type="button" class="clay-cover cover-${n}" data-cover="${n}" aria-label="${n+1}번 흙 조각 걷기">쓱쓱</button>`).join('')}</div><p class="story-bubble">${ROUTES[id].story}</p><button class="adv-primary" data-trail="wake" disabled>흙을 걷어 친구 깨우기</button>`,'흙 조각 세 곳을 눌러 걷어 줘.');}
 function recruit(){mode='recruit';shell(`${FRIEND_NAMES[ROUTES[id].who]} 토우가 깨어났어!`,`<div class="recruit-stage">${actor()}<span class="recruit-burst">새 친구!</span></div><h3 class="ability-name">${ROUTES[id].reward}</h3><p class="story-bubble">${{frog:'두꺼비: 내가 폴짝 뛰면 흙이 퐁! 어디로 뛸까?',bird:'새: 땅에서는 안 보이는 길, 나랑 위에서 찾아봐!',turtle:'거북: 내가 받쳐 줄게. 넌 틈을 살펴봐!'}[ROUTES[id].who]}</p><button class="adv-primary" data-trail="play">새 능력 써 보기!</button>`);}
 function play(){mode='play';marks=[];pos={x:.12,y:.85};aim={x:.3,y:.42};goal=null;const r=ROUTES[id];shell(r.title,`<div class="trail-layout"><div class="trail-board ${r.kind}" tabindex="0" role="group" aria-label="${r.kind==='fly'?'새를 날릴 곳을 누르는 공중 탐색 지도':r.kind==='jump'?'두꺼비 착지점을 정하는 흙길':'거북이 받쳐 주는 세 돌 틈'}"><div class="trail-path"></div><div class="trail-gate">${id==='ridge'?'두 번째 무덤':'숨은 입구'}</div>${r.points.map((p,n)=>`<button type="button" class="trail-point point-${n}" data-point="${n}" style="left:${p.x*100}%;top:${p.y*100}%" aria-label="${n+1}번 ${r.kind==='fly'?'흔적':r.kind==='jump'?'흙더미':'돌 틈'}">${r.kind==='fly'?['≋','⋰','∩'][n]:r.kind==='jump'?'흙':'틈'}</button>`).join('')}<div class="trail-pilot">${actor()}</div>${r.kind==='jump'?'<div class="landing-ring" aria-hidden="true">＋</div>':''}</div><div class="trail-controls"><div class="trail-progress" aria-live="polite">0 / 3</div><p class="trail-message" role="status">${r.kind==='jump'?'흙더미 하나를 눌러 착지점을 골라 줘.':r.kind==='fly'?'지도를 누르면 새가 그곳으로 날아가!':'먼저 거북의 받침 자리를 골라 줘.'}</p>${r.kind==='fly'?'<div class="flight-pad"><button data-dir="0,-1" aria-label="위로 날기">↑</button><button data-dir="-1,0" aria-label="왼쪽으로 날기">←</button><button data-dir="0,1" aria-label="아래로 날기">↓</button><button data-dir="1,0" aria-label="오른쪽으로 날기">→</button></div>':''}<button class="adv-primary" data-trail="act">${r.kind==='jump'?'폴짝!':r.kind==='fly'?'여기 내려다보기':'거북아, 받쳐 줘!'}</button><button class="adv-primary hidden" data-trail="finish">길이 열렸다! 안으로</button></div></div>`,r.hint);update();root.querySelector('.trail-board').focus({preventScroll:true});}
 function update(message){const r=ROUTES[id],pilot=root.querySelector('.trail-pilot');if(pilot){pilot.style.left=pos.x*100+'%';pilot.style.top=pos.y*100+'%';}const ring=root.querySelector('.landing-ring');if(ring){ring.style.left=aim.x*100+'%';ring.style.top=aim.y*100+'%';}for(const b of root.querySelectorAll('[data-point]')){const done=marks.includes(Number(b.dataset.point));b.classList.toggle('cleared',done);b.textContent=done?'✓':r.kind==='fly'?['≋','⋰','∩'][Number(b.dataset.point)]:r.kind==='jump'?'흙':'틈';}const progress=root.querySelector('.trail-progress');if(progress)progress.textContent=`${marks.length} / 3`;if(message)root.querySelector('.trail-message').textContent=message;const act=root.querySelector('[data-trail="act"]');if(act){act.disabled=busy;act.classList.toggle('hidden',marks.length===3);}root.querySelector('[data-trail="finish"]')?.classList.toggle('hidden',marks.length!==3);root.querySelector('.trail-gate')?.classList.toggle('open',marks.length===3);}
 function mark(n){if(n<0){update(ROUTES[id].kind==='fly'?'새: 흔적 가까이 날아가서 살펴보자!':'두꺼비: 퐁! 이번엔 흙더미 쪽으로 뛰어 볼까?');onSound('retry');return;}if(!marks.includes(n))marks.push(n);onSound('solved');update(marks.length===3?'숨은 길이 이어졌어! 이제 조심조심 안으로.':ROUTES[id].kind==='fly'?['새: 작은 길 자국이 보여!','새: 땅의 색이 여기서 달라져!','새: 언덕 아래 입구가 보여!'][n]:'길이 조금 더 드러났어!');}
 async function act(){if(mode!=='play'||busy||marks.length===3)return;const r=ROUTES[id];if(r.kind==='fly'){mark(scanAt(id,pos,marks));return;}if(r.kind==='brace'){const target=r.points.findIndex((p,n)=>!marks.includes(n)&&Math.abs(p.x-aim.x)<.05);if(target<0){update('먼저 받칠 돌 틈 하나를 눌러 줘.');return;}root.querySelector(`[data-point="${target}"]`).classList.add('braced');busy=true;pos={x:r.points[target].x,y:.65};update('거북: 받쳤어! 이제 밝아진 틈을 눌러 봐.');return;}
  busy=true;const own=token,end={...aim},pilot=root.querySelector('.trail-pilot'),start={...pos};update('두꺼비: 하낫, 둘… 폴짝!');const animation=pilot.animate([{left:start.x*100+'%',top:start.y*100+'%'},{left:(start.x+end.x)*50+'%',top:(Math.min(start.y,end.y)-.2)*100+'%'},{left:end.x*100+'%',top:end.y*100+'%'}],{duration:reduced()?0:650,easing:'ease-in-out'});await animation.finished.catch(()=>{});if(own!==token)return;pos=end;busy=false;mark(jumpHit(end.x,end.y,marks));
 }
 function choosePoint(n){if(mode!=='play')return;const r=ROUTES[id],p=r.points[n];if(!p)return;if(r.kind==='brace'&&busy){if(root.querySelector(`[data-point="${n}"]`).classList.contains('braced')){busy=false;mark(n);}else update('거북이 받치고 있는 밝은 틈을 눌러 줘.');return;}if(busy)return;if(r.kind==='fly'){goal={...p};update('새: 저쪽으로 날아갈게!');}else{aim={...p};update(r.kind==='jump'?'착지점 준비! 폴짝 버튼을 눌러 줘.':'받침 자리 준비! 거북을 불러 줘.');}}
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.cover!==undefined){patches.add(Number(b.dataset.cover));b.classList.add('uncovered');b.disabled=true;onSound('retry');if(patches.size===3){const next=root.querySelector('[data-trail="wake"]');next.disabled=false;next.textContent='친구야, 일어나!';}return;}if(b.dataset.point!==undefined){choosePoint(Number(b.dataset.point));return;}if(b.dataset.dir){const [dx,dy]=b.dataset.dir.split(',').map(Number);pos=flyStep(pos,dx,dy);goal=null;update();return;}switch(b.dataset.trail){case'exit':hide();onExit();break;case'wake':if(wakeFriend(s,id,patches.size)){onSave();onSound('solved');recruit();}break;case'play':play();break;case'act':act();break;case'finish':if(completeRoute(s,id,marks)){onSave();const finished=id;hide();onFinish(finished);}break;}});
 root.addEventListener('pointerdown',e=>{const board=e.target.closest('.trail-board');if(!board||e.target.closest('button')||busy)return;const r=board.getBoundingClientRect(),p={x:Math.max(.05,Math.min(.95,(e.clientX-r.left)/r.width)),y:Math.max(.05,Math.min(.95,(e.clientY-r.top)/r.height))};if(ROUTES[id].kind==='fly')goal=p;else if(ROUTES[id].kind==='jump')aim=p;update();});
 root.addEventListener('keydown',e=>{if(mode!=='play')return;const dirs={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0]};if(dirs[e.key]&&ROUTES[id].kind==='fly'){e.preventDefault();pos=flyStep(pos,...dirs[e.key]);goal=null;update();}else if((e.key===' '||e.key==='Enter')&&e.target.classList.contains('trail-board')){e.preventDefault();act();}});
 function paint(t){for(const c of root.querySelectorAll('canvas')){const r=c.getBoundingClientRect(),dp=Math.min(devicePixelRatio||1,2),w=Math.round(r.width*dp),h=Math.round(r.height*dp);if(!w||!h)continue;if(c.width!==w||c.height!==h){c.width=w;c.height=h;}const ctx=c.getContext('2d');ctx.clearRect(0,0,w,h);drawCharacter(ctx,ROUTES[id].who,w/2,h*.94,Math.min(w,h)*.95,t,mode==='recruit'?'artifactRevealed':'idle',false,reduced());}}
 function hide(){token++;goal=null;busy=false;mode='';root.classList.add('hidden');root.innerHTML='';}
 return {open(route){if(!canRoute(s,route))return false;hide();id=route;last=0;patches=new Set();s.friends.includes(ROUTES[id].who)?play():wake();return true;},hide,tick(t){if(!mode)return;const dt=last?Math.max(0,t-last):0;last=t;if(mode==='play'&&goal){const dx=goal.x-pos.x,dy=goal.y-pos.y,d=Math.hypot(dx,dy),step=dt*.00065;if(d<=step){pos=goal;goal=null;}else{pos={x:pos.x+dx/d*step,y:pos.y+dy/d*step};}update();}paint(t);}};
}
